<div style="padding:12px 14px 8px;">
<script>
(function(){
  var _cs = document.currentScript;
  var NS = "http://www.w3.org/2000/svg";
  function el(tag, attrs, txt){
    var e = document.createElementNS(NS, tag);
    for (var k in attrs) e.setAttribute(k, attrs[k]);
    if (txt !== undefined) e.textContent = txt;
    return e;
  }
  var FONT = "-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif";
  function textW(s, fs, mult){ return Math.ceil(s.length * fs * mult); }
  var closes = [35582.07,35491.27,35874.26,35806.65,36009.40,36335.61,35751.43,35706.46,35800.89,35489.86,35460.27,35235.87,35154.76,35502.65,35518.55,35649.51,35041.86,35145.38,35664.62,35983.98,35584.46,36137.10,36176.55,35928.63,36107.96];
  var dates = ["15 sept.","16 sept.","17 sept.","18 sept.","21 sept.","22 sept.","23 sept.","24 sept.","25 sept.","28 sept.","29 sept.","30 sept.","1er oct.","2 oct.","5 oct.","6 oct.","7 oct.","8 oct.","9 oct.","13 oct.","14 oct.","15 oct.","16 oct.","19 oct.","20 oct."];
  var data = [];
  var dlab = [];
  for (var i = 1; i < closes.length; i++) {
    data.push(Math.round((closes[i] / closes[i-1] - 1) * 10000) / 100);
    dlab.push(dates[i]);
  }
  var n = data.length;
  var svg = document.createElementNS(NS, "svg");
  svg.setAttribute("viewBox","0 0 680 300");
  svg.setAttribute("width","100%");
  var margin = {left: 62, right: 24, top: 18, bottom: 46};
  var PW = 680 - margin.left - margin.right;
  var PH = 300 - margin.top - margin.bottom;
  var amax = Math.max.apply(null, data.map(function(v){ return Math.abs(v); }));
  var ymax = Math.ceil((amax + 0.2) * 2) / 2;
  function yS(v){ return margin.top + (ymax - v) / (2 * ymax) * PH; }
  function xS(i){ return margin.left + 15 + (i / (n - 1)) * (PW - 30); }
  var zeroY = yS(0);
  var barW = 14;
  var labelEls = [];

  // 1. gridlines
  var tmax = Math.floor(ymax);
  for (var t = -tmax; t <= tmax; t++) {
    if (t !== 0) {
      svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: yS(t), y2: yS(t), stroke: "#ececec", "stroke-width": "0.5"}));
    }
    labelEls.push(el("text", {x: margin.left - 6, y: yS(t) + 3, "text-anchor": "end", "font-size": "8.5", fill: "#aaaaaa", "font-family": FONT}, (t > 0 ? "+" : "") + t + " %"));
  }

  // 2. reference lines (one percent sessions)
  var refUp = yS(1), refDn = yS(-1);
  svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: refUp, y2: refUp, stroke: "#2e7d32", "stroke-width": "1", "stroke-dasharray": "3,3"}));
  svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: refDn, y2: refDn, stroke: "#7a3030", "stroke-width": "1", "stroke-dasharray": "3,3"}));
  labelEls.push(el("text", {x: margin.left + 10, y: refUp - 10, "text-anchor": "start", "font-size": "7", "font-weight": "700", fill: "#2e7d32", "font-family": FONT}, "SÉANCE +1 %"));
  labelEls.push(el("text", {x: margin.left + 10, y: refDn + 12, "text-anchor": "start", "font-size": "7", "font-weight": "700", fill: "#7a3030", "font-family": FONT}, "SÉANCE -1 %"));

  // 3. series (bars)
  for (var b = 0; b < n; b++) {
    var v = data[b];
    var top = v >= 0 ? yS(v) : zeroY;
    var h = Math.abs(yS(v) - zeroY);
    svg.appendChild(el("rect", {x: xS(b) - barW / 2, y: top, width: barW, height: h, fill: v >= 0 ? "#3a7a55" : "#8a3030"}));
  }

  // 4. axis lines
  svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: zeroY, y2: zeroY, stroke: "#d8d8d8", "stroke-width": "1"}));
  svg.appendChild(el("line", {x1: margin.left, x2: margin.left, y1: margin.top, y2: margin.top + PH, stroke: "#d8d8d8", "stroke-width": "1"}));

  // 5. event marker lines and endpoint dot
  var events = [
    {i: dlab.indexOf("9 oct."), side: "up", lines: ["9 OCT", "EMPLOIS -68 000", "HAUSSE : 40 % À 25 %"]},
    {i: dlab.indexOf("19 oct."), side: "down", lines: ["19 OCT", "MACKLEM + IPC", "TSX -0,69 %"]}
  ];
  events.forEach(function(ev){
    var ex = xS(ev.i), tipY = yS(data[ev.i]);
    var y1 = ev.side === "up" ? tipY : margin.top;
    var y2 = ev.side === "up" ? margin.top + PH : tipY;
    svg.appendChild(el("line", {x1: ex, x2: ex, y1: y1, y2: y2, stroke: "#1a3560", "stroke-opacity": "0.5", "stroke-width": "1", "stroke-dasharray": "2,3"}));
  });
  var pi = dlab.indexOf("9 oct.");
  var pv = data[pi];
  svg.appendChild(el("circle", {cx: xS(pi), cy: yS(pv), r: 3, fill: "#4a5568"}));

  // 6. pill
  var pillText = (pv >= 0 ? "+" : "") + pv.toFixed(2).replace(".", ",") + " %";
  var pillW = Math.ceil(pillText.length * 9 * 0.58) + 10;
  var pillH = 16;
  var pillX = xS(pi) - barW / 2 - 6 - pillW;
  if (pillX < margin.left) pillX = margin.left;
  var pillY = yS(pv) - pillH / 2;
  svg.appendChild(el("rect", {x: pillX, y: pillY, width: pillW, height: pillH, rx: 3, fill: "#e8a825"}));
  svg.appendChild(el("text", {x: pillX + pillW / 2, y: pillY + pillH / 2 + 3.5, "text-anchor": "middle", "font-size": "9", "font-weight": "700", fill: "#111111", "font-family": FONT}, pillText));

  // 7. labels
  events.forEach(function(ev){
    var ex = xS(ev.i), tipY = yS(data[ev.i]);
    var lw = 0;
    ev.lines.forEach(function(s){ lw = Math.max(lw, textW(s, 7, 0.68)); });
    var crowded = events.some(function(o){ return o.i !== ev.i && Math.abs(xS(o.i) - ex) < 85; });
    var nearRight = (ex + lw + 3) > (margin.left + PW);
    var useEnd = crowded || nearRight;
    var anchor = useEnd ? "end" : "start";
    var lx = useEnd ? ex + barW / 2 : ex + 3;
    var firstY;
    if (ev.side === "up") {
      firstY = tipY - 10 - (ev.lines.length - 1) * 9.5;
    } else {
      firstY = tipY + 12;
    }
    ev.lines.forEach(function(s, k){
      labelEls.push(el("text", {x: lx, y: firstY + k * 9.5, "text-anchor": anchor, "font-size": "7", "font-weight": "700", fill: "#1a3560", "font-family": FONT}, s));
    });
  });
  var xi = [0, 3, 6, 9, 12, 15, 17, 19, 21, 23];
  xi.forEach(function(k){
    labelEls.push(el("text", {x: xS(k), y: margin.top + PH + 14, "text-anchor": "middle", "font-size": "8", fill: "#999999", "font-family": FONT}, dlab[k]));
  });
  labelEls.forEach(function(e){ svg.appendChild(e); });

  _cs.parentNode.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source&nbsp;: YCharts, clôtures quotidiennes de l’indice composé S&amp;P/TSX, du 15 sept. au 20 oct. 2026&nbsp;; calculs de HDQ. &nbsp;|&nbsp; hdq.ca</div>
</div>
</div>
<p style="font-size:11px;color:#666;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;margin-top:6px;">Les variations sont mesurées d’une clôture à l’autre, et le 13 octobre est comparé au 9 octobre parce que la Bourse de Toronto était fermée le 12 octobre pour l’Action de grâce. Les probabilités de hausse citées dans le texte sont celles du marché rapportées par Wealth Professional, et non une estimation de HDQ.</p>
<h2>Pourquoi ce schéma compte avant le 28 octobre</h2>
<p>La Banque du Canada rendra sa décision le 28 octobre, et la Réserve fédérale se réunit les 27 et 28 octobre. Reuters a rapporté le 19 octobre que les marchés monétaires s’attendent à un maintien à 2,25&nbsp;% tout en intégrant une hausse de 25 points de base en décembre.</p>
<p>Entre le 16 septembre et le 20 octobre, l’indice composé S&amp;P/TSX a bougé d’au moins 1&nbsp;% lors de six séances sur 24. La conclusion à plus long terme de Werner De Bondt et Richard Thaler, publiée en 1985, est que les investisseurs ont tendance à accorder trop de poids aux nouvelles spectaculaires récentes. La semaine qui vient offre un test en direct du poids qu’aura un seul discours, une seule publication de données ou une seule décision d’une banque centrale.</p>',
'<div class="toolkit-section">
<div class="toolkit-section-label">Ce qu’ils ressentent</div>
<p>Les clients qui suivent les manchettes sur les taux ont probablement le tournis. Les données faibles sur l’emploi du 9 octobre ont ressemblé à une bonne nouvelle pour les marchés, ce qui n’a pas été le cas d’une lecture plus modérée de l’inflation le 19 octobre, de sorte que les règles semblent changer d’une semaine à l’autre. Les clients ayant une dette à taux variable ou un renouvellement hypothécaire à venir s’inquiètent d’une hausse le 28 octobre, tandis que les détenteurs de fonds obligataires sont ébranlés par la récente hausse des rendements. Derrière les deux se cache le désir de savoir si la prochaine manchette sera bonne ou mauvaise.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Quoi dire</div>
<div class="script-box">Merci de votre appel. Le marché réagit à la façon dont la Banque du Canada pourrait agir le 28 octobre, et non à un changement dans votre plan. L’inflation de septembre s’est établie à 3,1&nbsp;%, mais sans l’essence elle a ralenti à 2,2&nbsp;%, et les mesures fondamentales que la Banque suit le plus étroitement ont diminué. En même temps, le Canada a perdu 68&nbsp;000 emplois en septembre. Ces deux faits tirent dans des directions opposées, ce qui explique l’ampleur des mouvements quotidiens. Les marchés monétaires s’attendent à ce que la Banque maintienne son taux le 28 octobre et prévoient une possible hausse en décembre. Je ne sais pas dans quel sens ira la décision, et personne ne le sait. Ce que je peux faire, c’est confirmer que votre portefeuille est conçu pour bien résister dans un cas comme dans l’autre et examiner tout ce qui arrive à échéance au cours des douze prochains mois. Pouvons-nous planifier trente minutes cette semaine&nbsp;?</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Qui est touché</div>
<p><strong>Forte incidence&nbsp;:</strong> les clients détenant des fonds obligataires ou des FNB à revenu fixe, ceux dont l’hypothèque vient à renouvellement dans les douze prochains mois et les retraités qui tirent un revenu de portefeuilles à forte composante obligataire.</p>
<p><strong>Incidence variable&nbsp;:</strong> les clients ayant des portefeuilles équilibrés comprenant des actions sensibles aux taux, comme les banques, les services publics et les télécoms, qui ont évolué avec les rendements obligataires ces dernières séances.</p>
<p><strong>Avantage potentiel&nbsp;:</strong> les clients dont des CPG ou des liquidités arrivent bientôt à échéance et qui pourraient réinvestir à des taux plus élevés si les rendements demeurent élevés.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Liste de vérification</div>
<div class="checklist-item">Examiner la durée des titres à revenu fixe dans l’ensemble de la clientèle.</div>
<div class="checklist-item">Dresser la liste des clients dont l’hypothèque vient à renouvellement ou qui ont un emprunt à taux variable dans les douze prochains mois.</div>
<div class="checklist-item">Repérer les clients dont des CPG arrivent à échéance avant la fin de l’année.</div>
<div class="checklist-item">Vérifier quels clients ont communiqué avec le bureau après le 9 ou le 19 octobre.</div>
<div class="checklist-item">Ajouter au calendrier le 27 octobre (Réserve fédérale) et le 28 octobre (Banque du Canada).</div>
<div class="checklist-item">Consigner chaque conversation avec un client comme une discussion à caractère éducatif.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de suivi</div>
<div class="email-box" id="respond-email">
<strong>Objet&nbsp;:</strong> Où en sont les choses avant la décision de la Banque du Canada du 28 octobre<br><br>
Bonjour [Nom du client],<br><br>
Merci d’avoir discuté avec moi aujourd’hui. Voici un bref résumé de ce que nous avons abordé.<br><br>
Les marchés ont oscillé au cours des deux dernières semaines, les investisseurs tentant de juger si la Banque du Canada relèvera son taux cible du financement à un jour, à 2,25&nbsp;%, le 28 octobre. L’inflation de septembre a été de 3,1&nbsp;%, mais de 2,2&nbsp;% sans l’essence, et les mesures fondamentales ont diminué. Le Canada a aussi perdu 68&nbsp;000 emplois en septembre. Ces faits tirent dans des directions différentes, ce qui explique l’ampleur des mouvements quotidiens.<br><br>
Votre plan a été conçu pour résister à différents scénarios de taux. J’examinerai les points dont nous avons discuté et je confirmerai les prochaines étapes d’ici le [date].<br><br>
N’hésitez pas à m’appeler si quoi que ce soit change de votre côté.<br><br>
[Votre nom]<br><br>
<em>La présente communication est fournie à des fins éducatives seulement et ne constitue pas un conseil en placement personnalisé.</em>
</div>
<button class="btn-copy" onclick="copyEmail(''respond-email'', this)">Copier le courriel</button>
</div>',
'<div class="toolkit-section">
<div class="toolkit-section-label">Profils de clients à cibler</div>
<p><strong>Investisseurs autonomes ayant effectué des transactions autour du 9 ou du 19 octobre&nbsp;:</strong> ils viennent d’observer deux réactions de marché contradictoires, sans personne pour les expliquer.</p>
<p><strong>Détenteurs autonomes de FNB obligataires ou de fonds obligataires&nbsp;:</strong> la hausse des rendements paraît dans leurs relevés, et la décision du 28 octobre est le prochain test.</p>
<p><strong>Propriétaires d’entreprise ayant des emprunts à taux variable&nbsp;:</strong> une hausse en octobre ou en décembre touche directement leurs coûts.</p>
<p><strong>Ménages dont l’hypothèque vient à renouvellement&nbsp;:</strong> ils surveillent les rendements obligataires et les manchettes sur les taux pour la même raison.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Phrase d’accroche</div>
<div class="script-box">Je vous appelle parce que les deux dernières semaines ont donné aux investisseurs deux réactions opposées à la même question sur la Banque du Canada, et je voulais vous demander comment vous avez interprété ces fluctuations.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Proposition de valeur</div>
<p>Deux séances à dix jours d’intervalle ont montré un marché qui progresse après la perte de 68&nbsp;000 emplois et qui recule après une lecture plus modérée de l’inflation. Un investisseur qui gère seul son argent a tendance à lire chaque journée isolément, et la manchette la plus frappante donne le ton. C’est ainsi que fonctionnent la disponibilité et l’ancrage, et personne n’est là pour aider cet investisseur à freiner sa réaction.</p>
<p>Le conseiller offre un processus plutôt qu’une prédiction&nbsp;: un plan conçu pour résister quelle que soit la décision de la Banque du Canada le 28 octobre, et une seconde voix lorsque les manchettes se contredisent. Cette asymétrie est la fenêtre de prospection.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Questions de découverte</div>
<div class="checklist-item">Comment avez-vous suivi le dossier de la Banque du Canada ces deux dernières semaines&nbsp;?</div>
<div class="checklist-item">Avez-vous modifié quoi que ce soit dans votre portefeuille après le 9 ou le 19 octobre&nbsp;?</div>
<div class="checklist-item">Lorsqu’une publication de données paraît, comment décidez-vous si elle est une bonne ou une mauvaise nouvelle pour ce que vous détenez&nbsp;?</div>
